(function(){'use strict';const modal=document.getElementById('modal-tutorial');if(!modal)return;let raf=0;function sync(){raf=0;if(modal.classList.contains('hidden'))return;const v=window.visualViewport;modal.style.setProperty('--tutorial-viewport-width',(v?.width||window.innerWidth)+'px');modal.style.setProperty('--tutorial-viewport-left',(v?.offsetLeft||0)+'px');modal.style.setProperty('--tutorial-viewport-height',(v?.height||window.innerHeight)+'px');modal.style.setProperty('--tutorial-viewport-top',(v?.offsetTop||0)+'px');}function queue(){if(!raf)raf=requestAnimationFrame(sync);}window.addEventListener('resize',queue);window.visualViewport?.addEventListener('resize',queue);window.visualViewport?.addEventListener('scroll',queue);new MutationObserver(queue).observe(modal,{attributes:true,attributeFilter:['class']});window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);raf=0;});queue();})();
